# Generated by the app scripts/export-monitoring-contract.ts. Do not edit.
import json
CONTRACT = json.loads("{\"semantic_version\":\"1.2.0\",\"server_name\":\"signalbase-monitoring-v3\",\"instructions\":\"Two ways to be told about signals as they happen. A monitor watches a chosen set of companies and delivers their signals; an alert is a saved search that delivers every new signal matching its filters, from the whole database. Use a monitor when someone names accounts to follow, an alert when they describe criteria (a role, a sector, a geography, a round type). The search tools answer questions about history; these tools only deliver what arrives from now on. For an alert, run the matching search tool first with the criteria, show the user what it returns, then create the alert with the same filter parameters — the alert accepts the search endpoint's own parameter names (see the alert_filters concept), so the arguments carry over. Confirm the inbox: an alert emails one address, the account owner's unless email is given. Read list_monitors or list_alerts before creating anything, and reuse a fitting one instead of making a near-duplicate. One monitor carries one signal selection for every target it holds, so different selections mean different monitors; one alert carries one signal type and one filter set. These tools change a customer's account. Confirm the monitor and the list with the user before the first write of a conversation, add targets with dry_run:true whenever the list did not come from the user verbatim, and report what actually happened — added, skipped as already present, rejected as unparseable — rather than assuming the whole input landed. Targets resolve asynchronously. A pending target is matched by automatic research within minutes to hours and re-checked nightly; it delivers nothing until it resolves, and it needs no action from you. Never tell a user a pending target has failed or ask them to re-add it. Monitoring is forward-looking: adding a company does not replay signals it already has. Use the signal search tools for history. Stopping is update_monitor or update_alert with active:false, which keeps everything and can be undone. There is no delete tool; if someone asks to delete a monitor or an alert, say it is done from the Monitoring page. Company-level signals are what a monitor delivers. It does not return a company's decision-makers or contacts; people are searched separately. Custom signals extend the signal types. When someone wants an event the built-in types do not cover, first read list_custom_signal_definitions — the shared catalogue may already have it — and read its signals with search_custom_signals; a custom slug also goes into a monitor's signal_types. Otherwise create_custom_signal with a plain-English rule, poll get_custom_signal until it is ready, show the user the test leads, and start it with update_custom_signal only when they agree. A started definition's matches alert like any other signal. Monitors created here deliver by email to the API key's owner, and alerts to the inbox they name. Webhook delivery exists but is deliberately not exposed to connectors: attaching an endpoint returns a signing secret exactly once, and a secret must not pass through a model's context or a chat transcript. Direct anyone who wants webhook delivery to the Monitoring page or the REST API; never claim you can add, read or rotate a webhook here.\",\"tools\":[{\"name\":\"create_monitor\",\"description\":\"Create a monitor: a named group of watched companies with its own signal selection. Start here when someone wants to follow specific accounts rather than search. Returns the monitor id used by every other tool. The monitor starts empty — follow with add_monitor_targets. A team may hold at most 20 monitors. Free. Monitors created here deliver by email to the API key's owner, and alerts to the inbox they name. Webhook delivery exists but is deliberately not exposed to connectors: attaching an endpoint returns a signing secret exactly once, and a secret must not pass through a model's context or a chat transcript. Direct anyone who wants webhook delivery to the Monitoring page or the REST API; never claim you can add, read or rotate a webhook here.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"What this monitor watches, in the user's words — for example \\\"Key accounts\\\" or \\\"Series A prospects\\\".\"},\"signal_types\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{2,39}$\"},\"minItems\":1,\"maxItems\":20,\"description\":\"Signal types this monitor delivers. Built-in: funding_round, acquisition, job_change, hiring. funding_round: the company raises a round. acquisition: it acquires or is acquired. job_change: someone joins or leaves. hiring: it posts a new job. Also accepts the slug of a custom signal definition (for example stealth_exit, new_office, founding_hire); list them with GET /api/v2/signals/custom/definitions — an unknown slug is rejected. Applies to every target in the monitor — use separate monitors for different selections.\"}},\"required\":[\"name\",\"signal_types\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"list_monitors\",\"description\":\"List every monitor on the team with its signal selection, paused state and statistics: how many targets it holds, how many are matched to a company, signals in the last 30 days, and when it last delivered. Read this before creating a monitor so an existing one is reused rather than duplicated. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{},\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"get_monitor\",\"description\":\"Read one monitor with the same fields list_monitors returns. Use after a change to confirm the current state. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"monitor_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Monitor id returned by create_monitor or list_monitors.\"}},\"required\":[\"monitor_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"update_monitor\",\"description\":\"Change a monitor's name, its signal selection, or whether it is active. signal_types replaces the whole list rather than adding to it, so include every type that should remain. active:false pauses delivery and keeps every target, and active:true resumes it — this is the way to stop a monitor, and the only reversible one. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"monitor_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Monitor id returned by create_monitor or list_monitors.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255},\"signal_types\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{2,39}$\"},\"minItems\":1,\"maxItems\":20,\"description\":\"Signal types this monitor delivers. Built-in: funding_round, acquisition, job_change, hiring. funding_round: the company raises a round. acquisition: it acquires or is acquired. job_change: someone joins or leaves. hiring: it posts a new job. Also accepts the slug of a custom signal definition (for example stealth_exit, new_office, founding_hire); list them with GET /api/v2/signals/custom/definitions — an unknown slug is rejected. Applies to every target in the monitor — use separate monitors for different selections.\"},\"active\":{\"type\":\"boolean\",\"description\":\"false pauses delivery and keeps every target; true resumes it. This is how monitoring is stopped — there is no delete tool.\"}},\"required\":[\"monitor_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"add_monitor_targets\",\"description\":\"Add companies to a monitor, by website domain, LinkedIn company URL or LinkedIn member profile URL, up to 100 per call. Adding is idempotent: targets already in the monitor are reported as skipped rather than duplicated, and unparseable entries are reported without failing the call. Targets matched to a known company resolve immediately and start delivering; the rest are pending and researched automatically. A team may watch 1000 targets in total, and a call that would exceed that is rejected whole, adding nothing. Use dry_run:true first for any list the user has not seen you repeat back. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"monitor_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Monitor id returned by create_monitor or list_monitors.\"},\"targets\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},\"minItems\":1,\"maxItems\":100,\"description\":\"Company website domains, LinkedIn company URLs, or LinkedIn member profile URLs, in any mix. A profile URL monitors whichever company that person currently works at. Scheme, www., path and case are normalized away, so repeats of a target already in the monitor are skipped rather than duplicated. At most 100 per call.\"},\"dry_run\":{\"type\":\"boolean\",\"description\":\"true reports what this exact call would add, skip as already present, and reject as unparseable, plus the team's remaining capacity — and writes nothing. Use it to confirm a long list with the user before committing.\"}},\"required\":[\"monitor_id\",\"targets\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":true,\"openWorldHint\":true}},{\"name\":\"list_monitor_targets\",\"description\":\"List a monitor's targets with each one's resolution status, matched company and most recent signal. Filter by status to see what is still pending. Paginated, newest first; read total before assuming a page is the whole monitor. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"monitor_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Monitor id returned by create_monitor or list_monitors.\"},\"status\":{\"type\":\"string\",\"enum\":[\"resolved\",\"pending\"],\"description\":\"resolved: matched to a company, signals are flowing. pending: not matched yet, researched automatically and re-checked nightly, delivering nothing meanwhile. Omit for both.\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":200},\"offset\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":100000}},\"required\":[\"monitor_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"remove_monitor_targets\",\"description\":\"Stop watching specific companies in one monitor, by the same identifiers add_monitor_targets accepts or by target id. Entries that match nothing are reported in not_found rather than failing the call. Removing every target leaves the monitor in place and delivering nothing; to stop a whole monitor use update_monitor with active:false instead. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"monitor_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Monitor id returned by create_monitor or list_monitors.\"},\"targets\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},\"minItems\":1,\"maxItems\":100,\"description\":\"Company website domains, LinkedIn company URLs, or LinkedIn member profile URLs, in any mix. A profile URL monitors whichever company that person currently works at. Scheme, www., path and case are normalized away, so repeats of a target already in the monitor are skipped rather than duplicated. At most 100 per call.\"},\"target_ids\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255},\"minItems\":1,\"maxItems\":100,\"description\":\"Target ids as returned by list_monitor_targets.\"}},\"required\":[\"monitor_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":true,\"openWorldHint\":true}},{\"name\":\"create_alert\",\"description\":\"Create an alert: a saved signal search that emails every NEW matching signal as it arrives, across the whole database — no company list needed. Use it when someone wants to be told about future signals that fit criteria (a role, a sector, a geography, a round type) rather than about named accounts. filters are the signal search's own parameters, so run the matching search first, confirm the results look right, then pass the same arguments here. One signal type per alert; one inbox per alert (email, default the account owner's). Returns the alert with ignored listing any parameter dropped as meaningless on an alert. A team may hold 50 alerts; an inbox receives at most 50 alert emails a day across all alerts pointed at it. Creating is free; each email sent costs 1 credit.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"What this alert catches, in the user's words — for example \\\"Heads of talent joining AI biotech\\\".\"},\"signal_type\":{\"type\":\"string\",\"enum\":[\"funding_round\",\"acquisition\",\"job_change\",\"hiring\"],\"description\":\"Which signal the alert watches. job_change: someone takes a new role. hiring: a company posts a job. funding_round: a company raises. acquisition: a company is bought or buys. One type per alert.\"},\"filters\":{\"type\":\"object\",\"additionalProperties\":{\"anyOf\":[{\"type\":\"string\",\"maxLength\":2000},{\"type\":\"number\"},{\"type\":\"boolean\"},{\"type\":\"array\",\"items\":{\"type\":\"string\",\"maxLength\":500},\"maxItems\":100}]},\"propertyNames\":{\"minLength\":1,\"maxLength\":100},\"description\":\"The search parameters this alert matches on, keyed exactly as the signal search endpoint for its type names them (see the alert_filters concept and the search docs): for job_change e.g. departments, seniorities, positions, new_role, countries, categories, search; for hiring e.g. title, departments, seniorities, countries, categories; for funding_round e.g. round, amount_min, countries, categories, investors; for acquisition e.g. acquirer_domain, countries, categories. Lists may be arrays or comma-separated strings. Pagination, sort, count and date parameters are ignored and reported back — an alert is forward-looking. At least one narrowing filter is required.\"},\"email\":{\"type\":\"string\",\"minLength\":3,\"maxLength\":320,\"description\":\"The one inbox this alert emails. Omit to use the account owner's sign-in address. Exactly one address per alert; create another alert for another inbox.\"}},\"required\":[\"name\",\"signal_type\",\"filters\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"list_alerts\",\"description\":\"List every alert on the team — those created here and those created on the search screen — with its signal type, filters, inbox, paused state and delivery statistics (emails in the last 30 days, last delivery). Read this before creating an alert so an existing one is updated rather than duplicated. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{},\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"get_alert\",\"description\":\"Read one alert with the same fields list_alerts returns. Use after a change to confirm the current state. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"alert_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Alert id returned by create_alert or list_alerts.\"}},\"required\":[\"alert_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"update_alert\",\"description\":\"Change an alert's name, its filters, the inbox it emails (email: null returns it to the account owner's address), or whether it is active. filters replaces the whole set, so include every parameter that should remain; the signal type is fixed. An alert created on the search screen belongs to the person who made it: only that person's own API key can change it, and its filters never change here. active:false pauses delivery and keeps the alert — this is the way to stop one, and it is reversible. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"alert_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255,\"description\":\"Alert id returned by create_alert or list_alerts.\"},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":255},\"filters\":{\"type\":\"object\",\"additionalProperties\":{\"anyOf\":[{\"type\":\"string\",\"maxLength\":2000},{\"type\":\"number\"},{\"type\":\"boolean\"},{\"type\":\"array\",\"items\":{\"type\":\"string\",\"maxLength\":500},\"maxItems\":100}]},\"propertyNames\":{\"minLength\":1,\"maxLength\":100},\"description\":\"Replaces the whole filter set (same shape as create_alert). The signal type cannot change; create a new alert for another type.\"},\"email\":{\"anyOf\":[{\"type\":\"string\",\"minLength\":3,\"maxLength\":320,\"description\":\"The one inbox this alert emails. Omit to use the account owner's sign-in address. Exactly one address per alert; create another alert for another inbox.\"},{\"type\":\"null\"}],\"description\":\"The one inbox this alert emails. null resets it to the account owner's sign-in address. Omit to leave unchanged.\"},\"active\":{\"type\":\"boolean\",\"description\":\"false pauses delivery and keeps the alert; true resumes it. This is how an alert is stopped — there is no delete tool.\"}},\"required\":[\"alert_id\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"create_custom_signal\",\"description\":\"Define a new kind of signal in plain English — one the built-in types (funding, acquisitions, job changes, hiring) do not cover, such as a rebrand, a first sales leader, a partnership announcement or a product launch. Give it a name and a description that says what a post must state about the author's own company to count. The definition is compiled into search phrases and a matching rule and test-run against recent posts, which takes a few minutes: read it back with get_custom_signal until its status is ready, show the user the test leads, and only then start it with update_custom_signal active:true. Nothing is swept until it is started. With targets (domains or LinkedIn company URLs) it only watches those companies; without, it sweeps every post. A team may hold 5 definitions and the feature needs a Pro plan. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\",\"minLength\":3,\"maxLength\":80,\"description\":\"A short name for the signal, in the user's words — for example \\\"Rebrands\\\" or \\\"Hiring a first sales leader\\\". The slug is derived from it.\"},\"description\":{\"type\":\"string\",\"minLength\":20,\"maxLength\":1500,\"description\":\"What a post must say for it to count, as a plain-English rule about the author's own company: the event, what makes it that event and not a neighbour of it, and anything that must be excluded. Two or three sentences. This is compiled into search phrases and a matching rule, so write the rule, not a list of keywords.\"},\"targets\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":500},\"minItems\":1,\"maxItems\":100,\"description\":\"Company website domains or LinkedIn company URLs. Given, the definition only sweeps posts from these companies (through a monitor that watches the new slug); omitted, it sweeps globally. At most 100.\"}},\"required\":[\"name\",\"description\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"list_custom_signal_definitions\",\"description\":\"List the custom signal definitions this team can read: the global catalogue everyone shares (for example stealth_exit, new_office, founding_hire) and the team's own, each with its slug, what counts as a match and the fields its signals carry. The team's own also show status, test results and how many signals they have produced. Read this before creating a definition — a global one may already cover the ask — and to find the slug for search_custom_signals or a monitor's signal_types. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"include_disabled\":{\"type\":\"boolean\",\"description\":\"true also lists definitions that are not currently swept (paused, disabled, failed, still compiling). Default false: only definitions producing signals now.\"}},\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"get_custom_signal\",\"description\":\"Read one of the team's own definitions: status (compiling → testing → ready → active, or paused, failed), the compile error if any, the last test run with the leads it found, and signal counts. Use it to poll after create_custom_signal and to confirm a change. Global catalogue definitions are not readable here; see list_custom_signal_definitions. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"slug\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{2,39}$\",\"description\":\"A definition slug as returned by list_custom_signal_definitions or create_custom_signal.\"}},\"required\":[\"slug\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"update_custom_signal\",\"description\":\"Start or pause one of the team's own definitions. active:true starts a ready definition (its test leads become its first signals) or resumes a paused one; active:false pauses an active one and keeps everything. Start only after the user has seen the test leads. There is no delete tool; removing a definition is done on the Custom signals page or over REST. Free.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"slug\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{2,39}$\",\"description\":\"A definition slug as returned by list_custom_signal_definitions or create_custom_signal.\"},\"active\":{\"type\":\"boolean\",\"description\":\"true starts a definition that is ready (its test leads become its first signals) or paused; false pauses an active one. Pausing keeps the definition, its slot and its signals. There is no delete tool; removing a definition is done on the Custom signals page or over REST.\"}},\"required\":[\"slug\",\"active\"],\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}},{\"name\":\"search_custom_signals\",\"description\":\"Read the signals custom definitions have produced — the global catalogue's and the team's own — filtered by definition slug, confidence, event date and company. Each row is one social post: a headline stating the event, verbatim evidence quotes, definition-specific attributes (a location, a role, a product), the post URL and the company. These are single-post evidence, not corroborated like funding rounds, so quote the evidence rather than restating the headline as fact and prefer min_confidence 0.8 for anything automated. count:true is free and sizes the question first. 1 credit per page of results, at most 50 rows a page.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"type\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"pattern\":\"^[a-z][a-z0-9_]{2,39}$\",\"description\":\"A definition slug as returned by list_custom_signal_definitions or create_custom_signal.\"},\"minItems\":1,\"maxItems\":20,\"description\":\"Definition slugs to read, from list_custom_signal_definitions. Omit for every definition the team can see (the global catalogue plus its own). An unknown slug matches nothing rather than failing.\"},\"min_confidence\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1,\"description\":\"Extractor confidence floor, 0 to 1. Custom signals are single-post evidence, not corroborated by a second source; 0.8 is a sensible floor for anything automated.\"},\"date_preset\":{\"type\":\"string\",\"enum\":[\"today\",\"yesterday\",\"last_7d\",\"last_14d\",\"last_30d\",\"last_60d\",\"last_90d\",\"last_6m\",\"last_1y\",\"last_2y\",\"last_3y\",\"last_5y\",\"all_time\",\"this_week\",\"this_month\",\"this_quarter\",\"this_year\",\"last_week\",\"last_month\",\"last_quarter\",\"last_year\"],\"description\":\"Relative window on the event date (today, last_7d, last_30d, last_90d, this_month, …). Takes precedence over date_from / date_to.\"},\"date_from\":{\"type\":\"string\",\"minLength\":4,\"maxLength\":40,\"description\":\"ISO-8601 lower bound on the event date.\"},\"date_to\":{\"type\":\"string\",\"minLength\":4,\"maxLength\":40,\"description\":\"ISO-8601 upper bound on the event date.\"},\"countries\":{\"type\":\"string\",\"minLength\":2,\"maxLength\":500,\"description\":\"Company HQ allowlist, comma-separated: ISO-2 codes (US,GB), English names, or regions (EU, DACH, NORDICS, NORTH_AMERICA, LATAM).\"},\"exclude_countries\":{\"type\":\"string\",\"minLength\":2,\"maxLength\":500,\"description\":\"Company HQ denylist, same format as countries.\"},\"company_domain\":{\"type\":\"string\",\"minLength\":3,\"maxLength\":3000,\"description\":\"Strict match on the company's website domain; up to 50, comma-separated. The reliable way to ask about named companies.\"},\"company_linkedin_url\":{\"type\":\"string\",\"minLength\":3,\"maxLength\":3000,\"description\":\"Strict match on the company's LinkedIn page URL; up to 50, comma-separated.\"},\"company_name\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"Exact, case-insensitive company name. Prefer company_domain when the domain is known.\"},\"search\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"Free text over headline, summary and company name.\"},\"keyword\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"The search phrase that found the post (partial match).\"},\"page\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":50,\"description\":\"Rows per page, default 20, at most 50.\"},\"count\":{\"type\":\"boolean\",\"description\":\"true returns only how many signals match, free of charge. Use it to size a question before paying for rows.\"}},\"additionalProperties\":false,\"$schema\":\"http://json-schema.org/draft-07/schema#\"},\"annotations\":{\"readOnlyHint\":true,\"destructiveHint\":false,\"idempotentHint\":false,\"openWorldHint\":true}}],\"concepts\":{\"target_kinds\":{\"domain\":\"A company website domain or any URL on it (acme.com, https://www.acme.com/about). Monitors that company.\",\"linkedin_company\":\"A LinkedIn company page URL. Monitors that company. Use when the user has the LinkedIn page but not the website.\",\"linkedin_profile\":\"A LinkedIn member profile URL. Monitors whichever company that person currently works at, so it follows them if they move.\"},\"target_status\":{\"resolved\":\"Matched to a company in the Signalbase database; its signals are delivered from now on.\",\"pending\":\"Not matched yet. Researched automatically and re-checked nightly. Delivers nothing meanwhile and needs no user action.\"},\"signal_types\":{\"funding_round\":\"The monitored company raised a round.\",\"acquisition\":\"The monitored company acquired, or was acquired.\",\"job_change\":\"Someone joined or left the monitored company.\",\"hiring\":\"The monitored company posted a new job.\",\"custom\":\"Any custom definition slug (list_custom_signal_definitions), for example stealth_exit, new_office, founding_hire or a slug the team created. A monitor with that slug delivers the definition's signals for its targets.\"},\"custom_signals\":{\"what\":\"A signal type defined as data: a plain-English rule for what a post about the author's own company must say. Each matching post becomes one signal under the definition's slug, with a headline, verbatim evidence quotes, definition-specific attributes and the post URL. Single-post evidence — not corroborated by a second source the way funding rounds are.\",\"catalogue\":\"Global definitions are shared by every team and already running; a team cannot change them. A team's own definitions are private to it: readable, startable and pausable only by that team.\",\"lifecycle\":\"create_custom_signal → compiling (search phrases and a rule are compiled from the description) → testing (a test run against recent posts) → ready (test leads available; nothing swept yet) → active (started; the test leads become its first signals, new matches arrive from now on) → paused / disabled. failed carries compileError: delete it on the Custom signals page and create it again with a clearer rule. Compiling and testing take minutes; poll get_custom_signal rather than assuming.\",\"writing_a_rule\":\"Describe the event in the author's own company's voice, what distinguishes it from neighbouring events, and what to exclude. Two or three sentences. Not a keyword list: the compiler derives search phrases itself. Weak: 'posts about sales'. Strong: 'the company announces hiring its first sales leader or founding sales team; exclude ordinary sales hires at companies that already have a sales team and recruiter posts about other companies'.\",\"delivery\":\"A started definition's signals alert like any other: a monitor whose signal_types include the slug delivers them for its targets, and the team's own definitions email their owner. Every custom-signal alert is reviewed by Signalbase before it is sent while the feature is in early access.\",\"limits\":\"5 definitions per team (paused ones count, removed ones do not); 100 targets per restricted definition; Pro plan required to create.\"},\"alerts\":{\"what\":\"A saved signal search that emails every new matching signal from the whole database. Not tied to a company list. One signal type, one filter set, one inbox per alert.\",\"workflow\":\"1. Run the search tool for the signal type with the user's criteria and review the results with them. 2. create_alert with the same parameter names and values. 3. Report back the alert's filters, inbox and any `ignored` parameters. The alert matches new signals with the search's own query, so it delivers exactly what that search would list.\",\"inbox\":\"email on create_alert / update_alert sets the one address an alert mails; omitted, the account owner's sign-in address is used. For a second inbox create a second alert.\",\"search_screen_alerts\":\"list_alerts also shows alerts created on the Signalbase search screen (source: dashboard). They belong to the person who made them: only that person's own API key can change their name, email or active state, and their filters cannot change here — create a new alert instead.\",\"opt_out\":\"Every alert email carries a one-click unsubscribe that pauses that alert for its recipient, so an inbox that did not ask for the mail can stop it without an account. If a recipient unsubscribes, the alert shows active:false; do not resume it without the recipient's say-so.\"},\"alert_filters\":{\"job_change\":{\"search_endpoint\":\"/api/v2/signals/job-changes\",\"company_filters\":\"search (free text over company and person fields), countries / exclude_countries (person country OR company HQ; ISO codes, names or region shortcuts), city, categories, subcategories, company_name, company_domain, company_linkedin_url (comma-separated lists).\",\"new_role\":\"Free-text match on the new title, e.g. 'talent' or 'Chief Technology Officer'. OR'd with positions.\",\"positions\":\"Comma-separated title patterns: ceo, cto, cfo, coo, vp of engineering, vp of sales, vp of marketing, head of product, head of growth, head of engineering, engineering manager, product manager, sales manager, marketing manager, founder, co-founder.\",\"departments\":\"Comma-separated functions: marketing, sales, engineering, product, design, operations, finance, people (people / talent / HR / recruiting), data, customer_success, growth, legal.\",\"seniorities\":\"Comma-separated levels: founder, c_level, vp, director, head, lead, manager.\",\"role_logic\":\"and (default) or or — how positions and departments combine.\",\"keyword\":\"Free-text match on the announcement post.\",\"source\":\"Signal source filter.\"},\"hiring\":{\"search_endpoint\":\"/api/v2/signals/hiring\",\"company_filters\":\"search, countries (job country OR company HQ), company_countries (HQ only), job_countries (job location only), exclude_countries, states (US), city, categories, subcategories, company_name, company_domain, company_linkedin_url, exclude_company_domain, team_size (e.g. 11-50,51-200,1000-plus), founded_year_min / founded_year_max.\",\"title\":\"Free-text match on the job title.\",\"description\":\"Free-text match on the job description body.\",\"positions\":\"Same title patterns as job_change.\",\"departments\":\"Same functions as job_change.\",\"seniorities\":\"Same levels as job_change.\",\"role_logic\":\"and (default) or or.\",\"applicants\":\"Applicant-count ranges, e.g. 0-10,11-50.\",\"work_mode\":\"remote — remote-only postings.\",\"role_scope\":\"software — software roles only.\",\"exclude_staffing_agencies\":\"true to drop staffing-agency postings.\",\"job_locations\":\"Comma-separated job locations (metros or countries).\",\"funding_rounds\":\"Only companies whose latest round is one of these, e.g. seed,series a.\",\"funding_investors\":\"Only companies backed by these investors.\",\"funding_investor_type\":\"pe or vc.\",\"headcount_growth_window\":\"1m, 3m, 6m, 9m or 12m, with headcount_growth_min (percent).\"},\"funding_round\":{\"search_endpoint\":\"/api/v2/signals/funding\",\"company_filters\":\"search, countries / exclude_countries (company HQ), categories, subcategories, industry, company_name, company_domain, company_linkedin_url, employee_count_min / employee_count_max, founded_year_min / founded_year_max.\",\"round\":\"Comma-separated round types, exactly as the search accepts them: pre-seed, seed, series a, series b, series c, series d, angel, grant, growth, debt, equity, ipo (case-insensitive).\",\"round_flavor\":\"Comma-separated flavors, e.g. bridge,extension.\",\"amount_min\":\"Minimum amount in whole currency units.\",\"amount_max\":\"Maximum amount in whole currency units.\",\"currency\":\"ISO currency code.\",\"investor_name\":\"Substring match on any investor.\",\"investors\":\"Comma-separated exact investor names (any of).\",\"investor_type\":\"pe or vc.\",\"verification_status\":\"e.g. verified.\"},\"acquisition\":{\"search_endpoint\":\"/api/v2/signals/acquisitions\",\"company_filters\":\"search, countries / exclude_countries (acquired company HQ), categories, subcategories, industry, company_name, company_domain, company_linkedin_url (acquired company), employee_count_min / employee_count_max, founded_year_min / founded_year_max.\",\"acquiring_company\":\"Name match on the buyer.\",\"acquirer_domain\":\"Buyer website domains (comma-separated).\",\"acquirer_linkedin_url\":\"Buyer LinkedIn company URLs.\",\"acquirer_countries\":\"Buyer HQ countries.\",\"exclude_acquirer_countries\":\"Buyer HQ countries to exclude.\",\"amount_min\":\"Minimum deal value in whole currency units.\",\"amount_max\":\"Maximum deal value.\",\"currency\":\"ISO currency code.\",\"verification_status\":\"e.g. verified.\"}},\"alert_filters_ignored\":\"Dropped and reported in `ignored`: page, limit, count, verbose, include_total, include_composition, count_companies, sort_by, sort_order, filter_version, dateFrom, dateTo, date_from, date_to, date_preset, date_basis, exclude_signal_ids, open_as_of, posted_min_days_ago, include_expired, workflow_evidence. An alert evaluates one new signal at a time, so paging, sorting, counting, result-shape flags and date windows have no meaning on it.\",\"alert_filters_rejected\":\"Refused with a message rather than dropped, because they change what the search returns: min_distinct_titles, max_company_postings (hiring-surge cohort filters over a company's postings).\",\"limits\":{\"monitors_per_team\":20,\"targets_per_team\":1000,\"targets_per_call\":100,\"alerts_per_team\":50,\"alert_emails_per_inbox_per_day\":50,\"custom_definitions_per_team\":5,\"custom_signal_rows_per_page\":50,\"credits\":\"Every monitoring, alert and custom-definition tool is free; no call consumes credits, except search_custom_signals, which costs 1 credit per page of rows (count:true is free). Each alert email that is sent costs 1 credit, like a webhook delivery.\"},\"delivery\":\"A monitor delivers by email to the API key's owner while it is active and holds at least one resolved target. An alert delivers by email to its inbox while it is active; an inbox receives at most alert_emails_per_inbox_per_day alert emails a day; every signal type an alert can select — job changes and hiring included — is emailed. Monitors created here deliver by email to the API key's owner, and alerts to the inbox they name. Webhook delivery exists but is deliberately not exposed to connectors: attaching an endpoint returns a signing secret exactly once, and a secret must not pass through a model's context or a chat transcript. Direct anyone who wants webhook delivery to the Monitoring page or the REST API; never claim you can add, read or rotate a webhook here.\"},\"examples\":[{\"name\":\"create_monitor\",\"arguments\":{\"name\":\"Key accounts\",\"signal_types\":[\"funding_round\",\"hiring\"]}},{\"name\":\"add_monitor_targets\",\"arguments\":{\"monitor_id\":\"29681a72-ed3d-41a8-b119-2c2942b34996\",\"targets\":[\"acme.com\",\"https://www.linkedin.com/company/initech/\",\"https://www.linkedin.com/in/jane-doe/\"],\"dry_run\":true}},{\"name\":\"list_monitor_targets\",\"arguments\":{\"monitor_id\":\"29681a72-ed3d-41a8-b119-2c2942b34996\",\"status\":\"pending\"}},{\"name\":\"update_monitor\",\"arguments\":{\"monitor_id\":\"29681a72-ed3d-41a8-b119-2c2942b34996\",\"active\":false}},{\"name\":\"create_alert\",\"arguments\":{\"name\":\"Heads of talent joining AI biotech\",\"signal_type\":\"job_change\",\"filters\":{\"departments\":\"people\",\"seniorities\":\"head,director,vp\",\"search\":\"AI biotech\"},\"email\":\"talent-leads@example.com\"}},{\"name\":\"create_alert\",\"arguments\":{\"name\":\"Seed and Series A in Germany\",\"signal_type\":\"funding_round\",\"filters\":{\"round\":[\"seed\",\"series a\"],\"countries\":\"DE\"}}},{\"name\":\"update_alert\",\"arguments\":{\"alert_id\":\"7f0a3b1c-2d4e-4f60-8a9b-0c1d2e3f4a5b\",\"email\":\"newinbox@example.com\",\"active\":true}},{\"name\":\"create_custom_signal\",\"arguments\":{\"name\":\"First sales leader\",\"description\":\"The author's own company announces hiring its first sales leader or is building its first sales team: a first VP Sales, Head of Sales, CRO or founding account executive. Exclude ordinary sales hires at companies that already have a sales team, and exclude posts by recruiters about other companies.\"}},{\"name\":\"get_custom_signal\",\"arguments\":{\"slug\":\"first_sales_leader_x7k2\"}},{\"name\":\"update_custom_signal\",\"arguments\":{\"slug\":\"first_sales_leader_x7k2\",\"active\":true}},{\"name\":\"search_custom_signals\",\"arguments\":{\"type\":[\"stealth_exit\",\"new_office\"],\"countries\":\"DE,AT,CH\",\"date_preset\":\"last_30d\",\"min_confidence\":0.8,\"limit\":20}},{\"name\":\"search_custom_signals\",\"arguments\":{\"company_domain\":\"acme.com\",\"count\":true}}],\"contract_hash\":\"14a34f46f9c5681f0051fe122cfb302e749a7008b96dd887e082ac55c43bfc1c\"}")
